import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';
import { RestoreRequest } from '../modules/backup-restore/models/backup.model';

@Injectable({ providedIn: 'root' })
export class RestoreMonitorService {
  private restoreProgressSubject = new BehaviorSubject<any>(null);
  public restoreProgress$ = this.restoreProgressSubject.asObservable();

  private restoreLogsSubject = new BehaviorSubject<any[]>([]);
  public restoreLogs$ = this.restoreLogsSubject.asObservable();

  startRestore(request: RestoreRequest): void {
    const logs: any[] = [];
    let progress = 0;

    this.addLog(logs, 'info', 'Iniciando proceso de restauración');

    const interval = setInterval(() => {
      progress += Math.random() * 20;

      if (progress >= 100) {
        progress = 100;
        clearInterval(interval);
        this.addLog(logs, 'success', 'Restauración completada exitosamente');
        this.restoreProgressSubject.next(null);
      }

      this.restoreProgressSubject.next({
        porcentaje: Math.min(progress, 100),
        etapa_actual: this.getRestoreStage(progress),
        detalle_etapa: this.getRestoreDetail(progress, request),
        tiempo_estimado: `${Math.ceil((100 - progress) / 10)} minutos`,
        tiempo_transcurrido: this.formatTime(progress)
      });

      this.addStageLogs(logs, progress, request);
      this.restoreLogsSubject.next([...logs]);
    }, 1000);
  }

  private getRestoreStage(progress: number): string {
    if (progress <= 25) return 'Preparando restauración';
    if (progress <= 50) return 'Restaurando base de datos';
    if (progress <= 75) return 'Restaurando archivos';
    return 'Finalizando configuración';
  }

  private getRestoreDetail(progress: number, request: RestoreRequest): string {
    if (progress <= 25) return request.modo_prueba ? 'Modo prueba activado' : 'Verificando integridad';
    if (progress <= 50) return request.componentes?.base_datos ? 'Importando datos' : 'Saltando base de datos';
    if (progress <= 75) return request.componentes?.archivos ? 'Copiando archivos' : 'Saltando archivos';
    return 'Aplicando configuración final';
  }

  private addLog(logs: any[], tipo: string, mensaje: string): void {
    logs.push({
      tipo,
      mensaje,
      timestamp: new Date()
    });
  }

  private addStageLogs(logs: any[], progress: number, request: RestoreRequest): void {
    if (progress >= 25 && progress < 30 && !logs.some(l => l.mensaje.includes('base de datos'))) {
      this.addLog(logs, 'info', 'Iniciando restauración de base de datos');
    }
    if (progress >= 50 && progress < 55 && !logs.some(l => l.mensaje.includes('archivos'))) {
      this.addLog(logs, 'info', 'Iniciando restauración de archivos');
    }
    if (progress >= 75 && progress < 80) {
      this.addLog(logs, 'warning', 'Verificando permisos y configuraciones');
    }
  }

  private formatTime(progress: number): string {
    const seconds = Math.floor(progress / 10);
    const minutes = Math.floor(seconds / 60);
    const remainingSeconds = seconds % 60;
    return `${minutes.toString().padStart(2, '0')}:${remainingSeconds.toString().padStart(2, '0')}:00`;
  }
}
