import { Injectable } from '@angular/core';
import { Observable, BehaviorSubject, of } from 'rxjs';
import { map, catchError, tap } from 'rxjs/operators';
import { BackupApiService } from '../../../core/services/api/backup-api.service';
import { Backup, BackupRequest, BackupProgress, CloudProvider, CLOUD_PROVIDERS, RestoreRequest } from '../models/backup.model';

interface BackupState {
  backups: Backup[];
  selectedBackup: Backup | null;
  loading: boolean;
  error: string | null;
  pagination: {
    current_page: number;
    per_page: number;
    total: number;
    last_page: number;
  };
}

const initialState: BackupState = {
  backups: [],
  selectedBackup: null,
  loading: false,
  error: null,
  pagination: {
    current_page: 1,
    per_page: 15,
    total: 0,
    last_page: 0
  }
};

@Injectable({ providedIn: 'root' })
export class BackupFacade {
  private state = new BehaviorSubject<BackupState>(initialState);
  private backupProgressSubject = new BehaviorSubject<BackupProgress | null>(null);

  public backupProgress$ = this.backupProgressSubject.asObservable();
  public backups$ = this.state.pipe(map(s => s.backups));
  public loading$ = this.state.pipe(map(s => s.loading));
  public pagination$ = this.state.pipe(map(s => s.pagination));

  constructor(private backupApi: BackupApiService) {}

  getCloudProviders(): CloudProvider[] {
    return CLOUD_PROVIDERS;
  }

  loadBackups(page: number = 1, perPage: number = 15): void {
    const currentState = this.state.getValue();
    this.state.next({ ...currentState, loading: true });

    this.backupApi.getPaginated({ page, per_page: perPage }).subscribe({
      next: (response: any) => {
        this.state.next({
          ...currentState,
          backups: response.data,
          pagination: response.meta,
          loading: false
        });
      },
      error: (error) => {
        this.state.next({ ...currentState, loading: false, error: error.message });
        this.showError('Error al cargar backups', error.message);
      }
    });
  }

 createBackup(request: BackupRequest): Observable<Backup | null> {
  this.startBackupProgress();

  const apiRequest = {
    descripcion: request.descripcion,
    origen_nube: request.origen_nube,
    tipo: request.tipo,
    ruta_archivo_local: request.ruta_archivo_local,
    ruta_personalizada: request.ruta_personalizada,
    origen: request.origen || 'sistema',
    solo_nube: request.solo_nube || false,
    api_referencia: request.api_referencia,
    encriptar: request.encriptar,
    comprimir: request.comprimir,
    nivel_compresion: request.nivel_compresion,
    password_encriptacion: request.password_encriptacion
  };

  return this.backupApi.create(apiRequest).pipe(
    tap((backup: Backup) => {
      const currentState = this.state.getValue();
      this.state.next({
        ...currentState,
        backups: [backup, ...currentState.backups]
      });
      this.completeBackupProgress();
      this.showSuccess('Backup creado exitosamente', `Backup guardado en ${this.getProviderLabel(request.origen_nube)}`);
    }),
    catchError((error) => {
      this.completeBackupProgress();
      this.showError('Error al crear backup', error.error?.message || 'Ocurrió un error');
      return of(null);
    })
  );
}

  deleteBackup(id: number): Observable<boolean> {
    return this.backupApi.delete(id).pipe(
      tap(() => {
        const currentState = this.state.getValue();
        const backups = currentState.backups.filter(b => b.backup_id !== id);
        this.state.next({ ...currentState, backups });
        this.showSuccess('Backup eliminado', 'El backup fue eliminado exitosamente');
      }),
      map(() => true),
      catchError((error) => {
        this.showError('Error al eliminar', error.error?.message);
        return of(false);
      })
    );
  }

  downloadBackup(id: number, filename?: string): void {
    this.backupApi.download(id).subscribe({
      next: (blob: Blob) => {
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = filename || `backup_${id}.zip`;
        a.click();
        window.URL.revokeObjectURL(url);
        this.showSuccess('Descarga iniciada', 'El backup se está descargando');
      },
      error: (error) => {
        this.showError('Error al descargar', error.error?.message);
      }
    });
  }

  validateIntegrity(id: number): Observable<boolean> {
    return this.backupApi.validateIntegrity(id).pipe(
      tap((result: any) => {
        if (result.valid) {
          this.showSuccess('Integridad verificada', result.message);
        } else {
          this.showWarning('Problema de integridad', result.message);
        }
      }),
      map((result: any) => result.valid),
      catchError((error) => {
        this.showError('Error al validar', error.error?.message);
        return of(false);
      })
    );
  }

  // Backup local SIEMPRE está activo
  testConnection(provider: string): Observable<{ success: boolean; message?: string }> {
    if (provider === 'local') {
      return of({
        success: true,
        message: '✅ Almacenamiento local disponible y activo'
      });
    }
    return this.backupApi.testConnection(provider);
  }

  getProviderLabel(value: string): string {
    const provider = CLOUD_PROVIDERS.find(p => p.value === value);
    return provider?.label || value;
  }

  getProviderIcon(value: string): string {
    const provider = CLOUD_PROVIDERS.find(p => p.value === value);
    return provider?.icon || '💾';
  }

  showSuccess(title: string, message: string): void {
    console.log(`✅ ${title}: ${message}`);
  }

  showError(title: string, message: string): void {
    console.error(`❌ ${title}: ${message}`);
  }

  showWarning(title: string, message: string): void {
    console.warn(`⚠️ ${title}: ${message}`);
  }

  showInfo(title: string, message: string): void {
    console.log(`ℹ️ ${title}: ${message}`);
  }

  private startBackupProgress(): void {
    let progress = 0;
    const interval = setInterval(() => {
      progress += 10;
      this.backupProgressSubject.next({
        porcentaje: Math.min(progress, 90),
        etapa: this.getProgressStage(progress),
        tiempo_transcurrido: this.formatTime(progress),
        detalles: 'Procesando backup...'
      });

      if (progress >= 90) {
        clearInterval(interval);
      }
    }, 500);
  }
showConfirm(title: string, message: string, onConfirm: () => void): void {
  // Usar el servicio de notificaciones o window.confirm
  if (confirm(`${title}\n\n${message}`)) {
    onConfirm();
  }
}

  private completeBackupProgress(): void {
    this.backupProgressSubject.next({
      porcentaje: 100,
      etapa: 'Completado',
      tiempo_transcurrido: '00:00',
      detalles: 'Backup finalizado exitosamente'
    });

    setTimeout(() => {
      this.backupProgressSubject.next(null);
    }, 2000);
  }

  private getProgressStage(progress: number): string {
    if (progress <= 30) return 'Recopilando datos...';
    if (progress <= 60) return 'Comprimiendo archivos...';
    if (progress <= 80) return 'Encriptando datos...';
    return 'Guardando en almacenamiento...';
  }

restoreBackup(request: RestoreRequest): Observable<any> {
  console.log('📤 Facade: Enviando restauración al backend:', request);
  return this.backupApi.restore(request.id_backup, request).pipe(
    tap((response) => {
      console.log('✅ Respuesta del backend:', response);
      this.showSuccess('Restauración iniciada', 'El proceso de restauración ha comenzado');
    }),
    catchError((error) => {
      console.error('❌ Error en API de restauración:', error);
      this.showError('Error en restauración', error.error?.message || 'Ocurrió un error');
      return of(null);
    })
  );
}
  private formatTime(progress: number): string {
    const seconds = Math.floor(progress / 10);
    return `${Math.floor(seconds / 60)}:${(seconds % 60).toString().padStart(2, '0')}`;
  }
}
