import { Component, OnInit, Output, EventEmitter, Input, ChangeDetectorRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormBuilder, FormGroup, Validators, ReactiveFormsModule } from '@angular/forms';
import { BackupFacade } from '../../facades/backup.facade';
import { BackupRequest, CLOUD_PROVIDERS } from '../../models/backup.model';

@Component({
  selector: 'app-backup-form',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './backup-form.component.html',
  styleUrls: ['./../../backup-restore.component.less']
})
export class BackupFormComponent implements OnInit {
  @Output() submitted = new EventEmitter<BackupRequest>();
  @Output() cancelled = new EventEmitter<void>();
  @Input() proveedoresActivos: string[] = [];

  backupForm!: FormGroup;
  currentStep = 1;
  cloudProviders = CLOUD_PROVIDERS;
  testConexionResultado: { estado: string; mensaje: string } | null = null;
  showPassword = false;

  tipoOptions = [
    { value: 'completo', label: 'Completo (BD + Archivos)', icon: '📦', description: 'Incluye base de datos, archivos y configuración' },
    { value: 'base_datos', label: 'Solo Base de Datos', icon: '🗄️', description: 'Solo la base de datos del sistema' },
    { value: 'archivos', label: 'Solo Archivos', icon: '📁', description: 'Archivos subidos y logs del sistema' },
    { value: 'configuracion', label: 'Solo Configuración', icon: '⚙️', description: 'Configuración del sistema y .env' }
  ];

  constructor(
    private fb: FormBuilder,
    private backupFacade: BackupFacade,
    private cdr: ChangeDetectorRef  // ← IMPORTANTE: Añadir ChangeDetectorRef
  ) {}

  ngOnInit(): void {
    this.initForm();
  }

  private initForm(): void {
  this.backupForm = this.fb.group({
    descripcion: ['', [Validators.required, Validators.minLength(10), Validators.maxLength(500)]],
    origen_nube: ['local', Validators.required],
    tipo: ['completo', Validators.required],
    ruta_archivo_local: [''],  // ← QUITAR required
    ruta_personalizada: [''],  // ← AGREGAR
    solo_nube: [false],  // ← AGREGAR
    api_referencia: [''],
    encriptar: [false],
    comprimir: [true],
    nivel_compresion: [5, [Validators.min(1), Validators.max(9)]],
    password_encriptacion: [''],
    tamano_mb: [0]
  });

  // Validación condicional
  this.backupForm.get('origen_nube')?.valueChanges.subscribe(origen => {
    const rutaControl = this.backupForm.get('ruta_archivo_local');
    const apiControl = this.backupForm.get('api_referencia');

    if (origen === 'local') {
      rutaControl?.clearValidators();  // ← NO required
      apiControl?.clearValidators();
    } else {
      rutaControl?.clearValidators();
      apiControl?.setValidators([Validators.required, Validators.minLength(10)]);
    }

    rutaControl?.updateValueAndValidity();
    apiControl?.updateValueAndValidity();
    this.backupForm.updateValueAndValidity();
  });
}

  proveedorActivo(providerValue: string): boolean {
    if (providerValue === 'local') {
      return true;
    }
    return this.proveedoresActivos.includes(providerValue);
  }


  testConnection(): void {
    const origen = this.backupForm.get('origen_nube')?.value;
    if (origen !== 'local') {
      this.backupFacade.testConnection(origen).subscribe({
        next: (result) => {
          if (result.success) {
            this.testConexionResultado = {
              estado: 'success',
              mensaje: result.message || 'Conexión exitosa'
            };
          } else {
            this.testConexionResultado = {
              estado: 'error',
              mensaje: result.message || 'Error de conexión'
            };
          }
          setTimeout(() => {
            this.testConexionResultado = null;
          }, 3000);
        },
        error: () => {
          this.testConexionResultado = {
            estado: 'error',
            mensaje: 'Error de conexión con el servidor'
          };
          setTimeout(() => {
            this.testConexionResultado = null;
          }, 3000);
        }
      });
    }
  }

  getPasswordStrength(): string {
    const password = this.backupForm.get('password_encriptacion')?.value;
    if (!password) return 'weak';

    let strength = 0;
    if (password.length >= 8) strength++;
    if (password.length >= 12) strength++;
    if (/[a-z]/.test(password)) strength++;
    if (/[A-Z]/.test(password)) strength++;
    if (/[0-9]/.test(password)) strength++;
    if (/[^a-zA-Z0-9]/.test(password)) strength++;

    if (strength <= 2) return 'weak';
    if (strength <= 4) return 'medium';
    if (strength <= 6) return 'strong';
    return 'very-strong';
  }

  getPasswordStrengthText(): string {
    const strength = this.getPasswordStrength();
    switch(strength) {
      case 'weak': return 'Débil';
      case 'medium': return 'Media';
      case 'strong': return 'Fuerte';
      case 'very-strong': return 'Muy Fuerte';
      default: return 'Débil';
    }
  }

  getIncluyeTexto(tipo: string): string {
    const tipos: Record<string, string> = {
      completo: 'Base de datos + Archivos + Configuración',
      base_datos: 'Solo base de datos',
      archivos: 'Solo archivos',
      configuracion: 'Solo configuración'
    };
    return tipos[tipo] || tipo;
  }

  getOrigenTexto(origen: string): string {
    const provider = this.cloudProviders.find(p => p.value === origen);
    return provider?.label || origen;
  }

  nextStep(): void {
  console.log('=== Intentando avanzar ===');
  console.log('CurrentStep:', this.currentStep);

  if (this.currentStep === 1 && this.isStep1Valid()) {
    console.log('✅ Paso 1 válido, avanzando a paso 2');
    this.currentStep = 2;
  } else if (this.currentStep === 2 && this.isStep2Valid()) {
    console.log('✅ Paso 2 válido, avanzando a paso 3');
    this.currentStep = 3;
  } else {
    console.log('❌ Paso', this.currentStep, 'NO válido');
    // Marcar campos del paso actual como tocados
    this.markCurrentStepFieldsAsTouched();
  }
}

previousStep(): void {
  if (this.currentStep > 1) {
    this.currentStep--;
  } else {
    this.cancelled.emit();
  }
}
explorarRuta(): void {
  // Crear un input de tipo file para seleccionar directorio
  const input = document.createElement('input');
  input.type = 'file';
  input.setAttribute('webkitdirectory', '');
  input.setAttribute('directory', '');

  input.onchange = (event: any) => {
    const files = event.target.files;
    if (files && files.length > 0) {
      // Obtener la ruta del primer archivo seleccionado
      const fullPath = files[0].webkitRelativePath;
      const folderPath = fullPath.split('/')[0];

      // Obtener la ruta completa (esto es limitado por seguridad del navegador)
      // Mostramos un prompt para que el usuario confirme o ingrese manualmente
      const confirmedPath = prompt(
        'Ruta seleccionada:\n' + folderPath + '\n\n¿Desea usar esta ruta? Si no, ingrese una ruta manual:',
        folderPath
      );

      if (confirmedPath !== null) {
        this.backupForm.patchValue({ ruta_archivo_local: confirmedPath.trim() });
        const rutaControl = this.backupForm.get('ruta_archivo_local');
        rutaControl?.updateValueAndValidity();
        this.backupForm.updateValueAndValidity();
        this.cdr.detectChanges();

        if (confirmedPath.trim() === '') {
          this.backupFacade.showInfo('Ruta por defecto', 'Se usará la ubicación predeterminada del sistema');
        } else {
          this.backupFacade.showSuccess('Ruta guardada', `Los backups se guardarán en: ${confirmedPath}`);
        }
      }
    }
  };

  input.click();
}

// Validación del Paso 2: Todo es opcional, siempre es válido
private isStep2Valid(): boolean {
  // El paso 2 es siempre válido porque:
  // - Comprimir: opcional (true por defecto)
  // - Encriptar: opcional (false por defecto)
  // - Nivel de compresión: tiene valor por defecto (5)
  // - Contraseña: solo requerida si encriptar está activado
  const encriptar = this.backupForm.get('encriptar')?.value;

  if (encriptar) {
    const password = this.backupForm.get('password_encriptacion')?.value;
    if (!password || password.length < 4) {
      console.log('❌ Si encripta, la contraseña es requerida (mínimo 4 caracteres)');
      return false;
    }
  }

  console.log('✅ Paso 2 válido');
  return true;
}

// Marcar campos del paso actual como tocados para mostrar errores
private markCurrentStepFieldsAsTouched(): void {
  if (this.currentStep === 1) {
    this.backupForm.get('descripcion')?.markAsTouched();
    this.backupForm.get('tipo')?.markAsTouched();
    this.backupForm.get('ruta_archivo_local')?.markAsTouched();
    this.backupForm.get('api_referencia')?.markAsTouched();
  } else if (this.currentStep === 2) {
    this.backupForm.get('password_encriptacion')?.markAsTouched();
  }
}

private isStep1Valid(): boolean {
  const descripcion = this.backupForm.get('descripcion');
  const origen = this.backupForm.get('origen_nube');
  const tipo = this.backupForm.get('tipo');

  if (!descripcion?.value || descripcion.value.length < 10) {
    return false;
  }

  if (!tipo?.value) {
    return false;
  }

  if (origen?.value === 'local') {
    // CORREGIDO: Ruta es opcional, el backend usará carpeta por defecto
    const ruta = this.backupForm.get('ruta_archivo_local')?.value;
    if (ruta && ruta.trim() !== '' && ruta.length < 3) {
      return false;
    }
  } else {
    const api = this.backupForm.get('api_referencia')?.value;
    if (!api || api.length < 10) {
      return false;
    }
  }

  return true;
}

onSubmit(): void {
  if (this.backupForm.valid) {
    const formValue = { ...this.backupForm.value };

    // Si la ruta está vacía, NO enviar
    if (!formValue.ruta_archivo_local || formValue.ruta_archivo_local.trim() === '') {
      delete formValue.ruta_archivo_local;
    }

    // Agregar campos adicionales
    formValue.origen = 'sistema';
    formValue.solo_nube = formValue.solo_nube || false;

    const request: BackupRequest = formValue;
    this.submitted.emit(request);
  }
}

}
