import { Injectable } from '@angular/core';
import { Observable, of } from 'rxjs';
import { BackupFacade } from '../modules/backup-restore/facades/backup.facade';

@Injectable({ providedIn: 'root' })
export class CloudSyncService {
  constructor(private backupFacade: BackupFacade) {}

  syncAllProviders(): Observable<any> {
    this.backupFacade.showInfo('Sincronización', 'Sincronizando con todos los proveedores cloud');
    return of({ success: true });
  }

  getCloudConfigurations(): Observable<any[]> {
    const providers = this.backupFacade.getCloudProviders();
    const configs = providers
      .filter(p => p.value !== 'local')
      .map(p => ({
        proveedor: p.value,
        nombre: p.label,
        activo: false
      }));

    return of(configs);
  }

  testConnection(provider: string): Observable<{ success: boolean; message?: string }> {
    return this.backupFacade.testConnection(provider);
  }

  configureProvider(provider: string): void {
    this.backupFacade.showInfo('Configuración', `Configurando proveedor ${provider}`);
  }
}
