export interface Backup {
  backup_id: number;
  fecha: Date;
  usuario_id: number;
  usuario_nombre?: string;
  ruta_archivo: string;
  ruta_personalizada?: string;  // ← AGREGAR
  origen?: string;  // ← AGREGAR
  api_referencia: string | null;
  descripcion: string;
  origen_nube: 'local' | 'backblaze' | 'mega' | 'onedrive' | 'dropbox';
  tamanio_mb: number;
  encriptado: boolean;
  comprimido: boolean;
  integridad_verificada: boolean;
  solo_nube?: boolean;  // ← AGREGAR
  estado: 'activo' | 'completado' | 'fallido' | 'COMPLETADO';
  created_at?: Date;
  updated_at?: Date;
  deleted_at?: Date;
}

export interface BackupRequest {
  descripcion: string;
  origen_nube: string;
  tipo: string;
  ruta_archivo_local?: string;
  ruta_personalizada?: string;  // ← AGREGAR
  origen?: string;  // ← AGREGAR
  solo_nube?: boolean;  // ← AGREGAR
  api_referencia?: string;
  encriptar: boolean;
  comprimir: boolean;
  nivel_compresion?: number;
  password_encriptacion?: string;
}

export interface BackupValidation {
  valid: boolean;
  message: string;
  recommendation?: string;
}

export interface BackupProgress {
  porcentaje: number;
  etapa: string;
  tiempo_transcurrido: string;
  detalles: string;
}

export interface RestoreRequest {
  id_backup: number;
  origen: string;
  observaciones: string;
  modo: 'completa' | 'parcial';
  modo_prueba: boolean;
  componentes: {
    base_datos: boolean;
    usuarios: boolean;
    configuracion: boolean;
    archivos: boolean;
    datos: boolean;
  };
}

export interface CloudProvider {
  value: string;
  label: string;
  icon: string;
  freeSpace: string;
  description: string;
  color: string;
  needsApiKey: boolean;
}

