import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable, interval } from 'rxjs';
import { BackupRequest, BackupProgress } from '../modules/backup-restore/models/backup.model';

@Injectable({ providedIn: 'root' })
export class BackupMonitorService {
  private backupProgressSubject = new BehaviorSubject<BackupProgress | null>(null);
  public backupProgress$ = this.backupProgressSubject.asObservable();

  private currentInterval: any;

  startBackup(request: BackupRequest): void {
    let progress = 0;

    this.backupProgressSubject.next({
      porcentaje: 0,
      etapa: 'Iniciando backup...',
      tiempo_transcurrido: '00:00:00',
      detalles: `Creando backup: ${request.descripcion}`
    });

    this.currentInterval = setInterval(() => {
      progress += 10;

      if (progress >= 100) {
        this.completeBackup();
        clearInterval(this.currentInterval);
      } else {
        this.backupProgressSubject.next({
          porcentaje: progress,
          etapa: this.getStage(progress),
          tiempo_transcurrido: this.formatTime(progress),
          detalles: this.getDetails(progress, request)
        });
      }
    }, 1000);
  }

  private completeBackup(): void {
    this.backupProgressSubject.next({
      porcentaje: 100,
      etapa: 'Completado',
      tiempo_transcurrido: '00:00:00',
      detalles: 'Backup finalizado exitosamente'
    });

    setTimeout(() => {
      this.backupProgressSubject.next(null);
    }, 2000);
  }

  private getStage(progress: number): string {
    if (progress <= 30) return 'Recopilando datos...';
    if (progress <= 60) return 'Comprimiendo archivos...';
    if (progress <= 80) return 'Encriptando datos...';
    return 'Subiendo a almacenamiento...';
  }

  private getDetails(progress: number, request: BackupRequest): string {
    if (progress <= 30) return `Procesando ${request.tipo}`;
    if (progress <= 60) return `Comprimiendo con nivel ${request.nivel_compresion || 5}`;
    if (progress <= 80) return request.encriptar ? 'Aplicando encriptación AES-256' : 'Preparando archivos';
    return `Guardando en ${request.origen_nube}`;
  }

  private formatTime(progress: number): string {
    const seconds = Math.floor(progress / 10);
    const minutes = Math.floor(seconds / 60);
    const remainingSeconds = seconds % 60;
    return `${minutes.toString().padStart(2, '0')}:${remainingSeconds.toString().padStart(2, '0')}:00`;
  }
}
