import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { BaseApiService } from './../base-api.service';
import { Backup, BackupRequest, BackupValidation, RestoreRequest } from '../../../modules/backup-restore/models/backup.model';

@Injectable({ providedIn: 'root' })
export class BackupApiService extends BaseApiService<Backup> {
  protected endpoint = 'backups';

  constructor(http: HttpClient) {
    super(http);
  }

  override create(data: any): Observable<Backup> {
  return this.http.post<Backup>(`${this.baseUrl}/${this.endpoint}`, data);
}

  validateIntegrity(id: number): Observable<BackupValidation> {
    return this.http.post<BackupValidation>(`${this.baseUrl}/${this.endpoint}/${id}/validate`, {});
  }

restore(id: number, data: RestoreRequest): Observable<any> {
  console.log(`📡 API: Restaurando backup ${id} con datos:`, data);
  return this.http.post(`${this.baseUrl}/${this.endpoint}/${id}/restore`, data);
}

  estimateSize(data: BackupRequest): Observable<{ estimated_size_mb: number }> {
    return this.http.post<{ estimated_size_mb: number }>(`${this.baseUrl}/${this.endpoint}/estimate`, data);
  }

  download(id: number): Observable<Blob> {
    return this.http.get(`${this.baseUrl}/${this.endpoint}/${id}/download`, { responseType: 'blob' });
  }

  testConnection(provider: string): Observable<{ success: boolean; message?: string }> {
    return this.http.post<{ success: boolean; message?: string }>(`${this.baseUrl}/${this.endpoint}/test-connection`, { provider });
  }
}
