import { Component, Input, Output, EventEmitter } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Backup, RestoreRequest } from '../../models/backup.model';
import { BackupFacade } from '../../facades/backup.facade';

@Component({
  selector: 'app-restore-modal',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './restore-modal.component.html',
  styleUrls: ['./../../backup-restore.component.less']
})
export class RestoreModalComponent {
  @Input() backup: Backup | null = null;
  @Output() confirm = new EventEmitter<RestoreRequest>();
  @Output() cancel = new EventEmitter<void>();

  restoreData: RestoreRequest = {
    id_backup: 0,
    origen: '',
    observaciones: '',
    modo: 'completa',
    modo_prueba: false,
    componentes: {
      base_datos: true,
      usuarios: true,
      configuracion: false,
      archivos: false,
      datos: true
    }
  };

  validating = false;
  validationResult: { valid: boolean; message: string } | null = null;

  constructor(private backupFacade: BackupFacade) {}

  ngOnChanges(): void {
    if (this.backup) {
      this.restoreData.id_backup = this.backup.backup_id;
      this.restoreData.origen = this.backup.origen_nube;
      this.validateBackup();
    }
  }

  validateBackup(): void {
    if (!this.backup) return;

    this.validating = true;
    this.backupFacade.validateIntegrity(this.backup.backup_id).subscribe(valid => {
      this.validationResult = {
        valid: valid,
        message: valid
          ? '✅ El backup ha pasado la validación de integridad'
          : '⚠️ Advertencia: El backup no ha pasado la validación de integridad'
      };
      this.validating = false;
    });
  }

 onSubmit(): void {
  console.log('📤 Enviando solicitud de restauración:', this.restoreData);
  if (this.backup) {
    this.confirm.emit(this.restoreData);
  }
}

  onCancel(): void {
    this.cancel.emit();
  }

  getProviderIcon(): string {
    return this.backup ? this.backupFacade.getProviderIcon(this.backup.origen_nube) : '💾';
  }

  getProviderLabel(): string {
    return this.backup ? this.backupFacade.getProviderLabel(this.backup.origen_nube) : '';
  }

  formatFileSize(sizeMB: number): string {
    if (sizeMB < 1) return `${(sizeMB * 1024).toFixed(2)} KB`;
    if (sizeMB < 1024) return `${sizeMB.toFixed(2)} MB`;
    return `${(sizeMB / 1024).toFixed(2)} GB`;
  }

  formatDate(date: Date): string {
    return new Date(date).toLocaleString('es-ES', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  }
}
