import { Component, Output, EventEmitter, Input } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { OnInit } from '@angular/core';

interface CloudProvider {
  value: string;
  label: string;
  icon: string;
  enabled: boolean;
  apiKey: string;
  apiSecret: string;
  testResult: string;
  testSuccess: boolean;
}

interface BackupConfig {
  compressionLevel: number;
  compressByDefault: boolean;
  defaultPath: string;
  cloudProviders: {
    [key: string]: {
      enabled: boolean;
      apiKey: string;
      apiSecret: string;
    }
  };
}

@Component({
  selector: 'app-backup-config',
  standalone: true,
  imports: [CommonModule, FormsModule],
  template: `
    <div class="backup-config-modal">
      <div class="config-header">
        <h3>⚙️ Configuración de Backup</h3>
        <button class="close-btn" (click)="onClose()">✕</button>
      </div>

      <div class="config-tabs">
        <button class="tab" [class.active]="activeTab === 'cloud'" (click)="activeTab = 'cloud'">☁️ Servicios Cloud</button>
        <button class="tab" [class.active]="activeTab === 'compression'" (click)="activeTab = 'compression'">🗜️ Compresión</button>
      </div>

      <!-- Configuración Cloud -->
      <div *ngIf="activeTab === 'cloud'" class="config-panel">
        <div class="provider-card" *ngFor="let provider of cloudProviders">
          <div class="provider-header">
            <span class="provider-icon">{{ provider.icon }}</span>
            <span class="provider-name">{{ provider.label }}</span>
            <label class="toggle-switch">
              <input type="checkbox" [(ngModel)]="provider.enabled" (change)="onProviderToggle(provider)">
              <span class="slider"></span>
            </label>
          </div>

          <div class="provider-config" *ngIf="provider.enabled">
            <div class="form-group">
              <label>API Key / Token</label>
              <input type="password" [(ngModel)]="provider.apiKey" class="form-control"
                     placeholder="Ingrese su API Key">
            </div>
            <div class="form-group">
              <label>API Secret (opcional)</label>
              <input type="password" [(ngModel)]="provider.apiSecret" class="form-control">
            </div>
            <button class="btn-test" (click)="testConnection(provider)" [disabled]="testing">
              {{ testing ? 'Probando...' : '🔌 Probar conexión' }}
            </button>
            <div *ngIf="provider.testResult" class="test-result" [class.success]="provider.testSuccess">
              {{ provider.testResult }}
            </div>
          </div>
        </div>
      </div>

      <!-- Configuración de Compresión -->
      <div *ngIf="activeTab === 'compression'" class="config-panel">
        <div class="form-group">
          <label>Nivel de compresión por defecto: {{ defaultCompressionLevel }}</label>
          <input type="range" [(ngModel)]="defaultCompressionLevel" min="1" max="9" step="1" class="range">
          <div class="range-labels">
            <span>Más rápido</span>
            <span>Balanceado</span>
            <span>Más pequeño</span>
          </div>
        </div>

        <div class="form-group">
          <label>
            <input type="checkbox" [(ngModel)]="compressByDefault">
            Comprimir backups por defecto
          </label>
        </div>

        <div class="form-group">
          <label>Ruta por defecto para backups locales</label>
          <div class="path-input">
            <input type="text" [(ngModel)]="defaultPath" class="form-control" readonly>
            <button class="btn-browse" (click)="selectDefaultPath()">📁 Seleccionar</button>
          </div>
        </div>
      </div>

      <div class="config-footer">
        <button class="btn-cancel" (click)="onClose()">Cancelar</button>
        <button class="btn-save" (click)="saveConfig()">Guardar configuración</button>
      </div>
    </div>
  `,
  styles: [`
   // ============================================
// BACKUP CONFIG MODAL - ESTILOS CON VARIABLES GLOBALES
// ============================================

// Nota: Todas las variables CSS vienen definidas en themes.less
// Se acceden mediante var(--nombre-variable)

// ============================================
// MODAL PRINCIPAL
// ============================================
.backup-config-modal {
  background: var(--modal-bg);
  border-radius: 20px;
  box-shadow: var(--shadow-xl);
  width: 100%;
  max-height: 90vh;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  animation: modalSlideIn 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  border: 1px solid var(--modal-border);

  @keyframes modalSlideIn {
    from {
      opacity: 0;
      transform: translateY(-30px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }
}

// ============================================
// HEADER DEL MODAL
// ============================================
.config-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 20px 24px;
  border-bottom: 1px solid var(--border-color);
  background: var(--modal-header-bg);

  h3 {
    margin: 0;
    font-size: 20px;
    font-weight: 600;
    color: var(--text-primary);
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .close-btn {
    background: none;
    border: none;
    font-size: 24px;
    cursor: pointer;
    color: var(--text-muted);
    width: 32px;
    height: 32px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 8px;
    transition: all 0.3s;

    &:hover {
      background: var(--bg-hover);
      color: var(--danger);
      transform: rotate(90deg);
    }
  }
}

// ============================================
// TABS DEL MODAL
// ============================================
.config-tabs {
  display: flex;
  gap: 8px;
  padding: 0 24px;
  background: var(--bg-primary);
  border-bottom: 1px solid var(--border-color);

  .tab {
    padding: 12px 20px;
    background: none;
    border: none;
    color: var(--text-muted);
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s;
    position: relative;
    display: flex;
    align-items: center;
    gap: 8px;

    &:hover {
      color: var(--primary);
    }

    &.active {
      color: var(--primary);

      &::after {
        content: '';
        position: absolute;
        bottom: -1px;
        left: 0;
        right: 0;
        height: 2px;
        background: var(--primary);
      }
    }
  }
}

// ============================================
// PANEL DE CONFIGURACIÓN
// ============================================
.config-panel {
  flex: 1;
  overflow-y: auto;
  padding: 24px;
  background: var(--modal-bg);

  &::-webkit-scrollbar {
    width: 6px;
  }

  &::-webkit-scrollbar-track {
    background: var(--bg-tertiary);
    border-radius: 3px;
  }

  &::-webkit-scrollbar-thumb {
    background: var(--primary);
    border-radius: 3px;

    &:hover {
      background: var(--primary-hover);
    }
  }
}

// ============================================
// TARJETAS DE PROVEEDORES
// ============================================
.provider-card {
  background: var(--bg-tertiary);
  border-radius: 16px;
  border: 1px solid var(--border-color);
  margin-bottom: 20px;
  overflow: hidden;
  transition: all 0.3s;

  &:hover {
    border-color: var(--primary);
    box-shadow: var(--shadow-sm);
  }

  &:last-child {
    margin-bottom: 0;
  }

  .provider-header {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 16px 20px;
    background: var(--bg-primary);
    border-bottom: 1px solid var(--border-color);

    .provider-icon {
      font-size: 24px;
    }

    .provider-name {
      flex: 1;
      font-weight: 600;
      color: var(--text-primary);
      font-size: 15px;
    }

    .toggle-switch {
      position: relative;
      display: inline-block;
      width: 50px;
      height: 24px;

      input {
        opacity: 0;
        width: 0;
        height: 0;

        &:checked + .slider {
          background: var(--success);
        }

        &:checked + .slider:before {
          transform: translateX(26px);
        }
      }

      .slider {
        position: absolute;
        cursor: pointer;
        top: 0;
        left: 0;
        right: 0;
        bottom: 0;
        background: var(--border-color);
        transition: 0.3s;
        border-radius: 34px;

        &:before {
          position: absolute;
          content: "";
          height: 18px;
          width: 18px;
          left: 3px;
          bottom: 3px;
          background: white;
          transition: 0.3s;
          border-radius: 50%;
        }
      }
    }
  }

  .provider-config {
    padding: 20px;
    display: flex;
    flex-direction: column;
    gap: 16px;
  }
}

// ============================================
// FORMULARIO
// ============================================
.form-group {
  display: flex;
  flex-direction: column;
  gap: 8px;

  label {
    font-size: 13px;
    font-weight: 500;
    color: var(--text-primary);
    display: flex;
    align-items: center;
    gap: 6px;

    input[type="checkbox"] {
      width: 16px;
      height: 16px;
      margin: 0;
      cursor: pointer;
      accent-color: var(--primary);
    }
  }

  .form-control {
    width: 100%;
    padding: 12px 16px;
    border: 1px solid var(--input-border);
    border-radius: 8px;
    background: var(--input-bg);
    color: var(--text-primary);
    font-size: 14px;
    transition: all 0.3s;

    &:focus {
      outline: none;
      border-color: var(--input-focus);
      box-shadow: var(--input-focus-shadow);
    }

    &:read-only {
      background: var(--input-disabled-bg);
      cursor: pointer;
    }
  }
}

// ============================================
// RANGO (SLIDER)
// ============================================
.range {
  width: 100%;
  height: 6px;
  -webkit-appearance: none;
  background: var(--bg-primary);
  border-radius: 3px;
  outline: none;

  &::-webkit-slider-thumb {
    -webkit-appearance: none;
    width: 18px;
    height: 18px;
    background: var(--primary);
    border-radius: 50%;
    cursor: pointer;
    transition: all 0.3s;

    &:hover {
      transform: scale(1.2);
    }
  }
}

.range-labels {
  display: flex;
  justify-content: space-between;
  margin-top: 8px;
  font-size: 11px;
  color: var(--text-muted);
}

// ============================================
// RUTA DE ARCHIVOS
// ============================================
.path-input {
  display: flex;
  gap: 12px;
  align-items: center;

  .form-control {
    flex: 1;
  }

  .btn-browse {
    padding: 10px 16px;
    background: var(--bg-primary);
    border: 1px solid var(--border-color);
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.3s;
    color: var(--text-primary);
    font-size: 13px;
    white-space: nowrap;

    &:hover {
      background: var(--bg-hover);
      border-color: var(--primary);
      transform: translateY(-2px);
    }
  }
}

// ============================================
// BOTONES DE PRUEBA
// ============================================
.btn-test {
  padding: 12px 16px;
  background: var(--bg-primary);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.3s;
  color: var(--text-primary);
  font-size: 14px;
  font-weight: 500;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;

  &:hover:not(:disabled) {
    background: var(--bg-hover);
    border-color: var(--primary);
    transform: translateY(-2px);
  }

  &:disabled {
    opacity: 0.6;
    cursor: not-allowed;
  }
}

// ============================================
// RESULTADO DE PRUEBA
// ============================================
.test-result {
  margin-top: 8px;
  padding: 8px 12px;
  border-radius: 8px;
  font-size: 12px;
  background: var(--bg-tertiary);
  color: var(--text-muted);

  &.success {
    background: var(--success-light);
    color: var(--success);
  }

  &.error {
    background: var(--danger-light);
    color: var(--danger);
  }
}

// ============================================
// FOOTER DEL MODAL
// ============================================
.config-footer {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
  padding: 16px 24px;
  border-top: 1px solid var(--border-color);
  background: var(--modal-footer-bg);

  .btn-cancel {
    padding: 10px 20px;
    background: var(--bg-tertiary);
    border: 1px solid var(--border-color);
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.3s;
    color: var(--text-primary);
    font-size: 14px;
    font-weight: 500;

    &:hover {
      background: var(--bg-hover);
      transform: translateY(-2px);
    }
  }

  .btn-save {
    padding: 10px 24px;
    background: var(--gradient-primary);
    border: none;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.3s;
    color: white;
    font-size: 14px;
    font-weight: 600;

    &:hover {
      transform: translateY(-2px);
      box-shadow: var(--shadow-sm);
    }
  }
}

// ============================================
// RESPONSIVE
// ============================================
@media (max-width: 768px) {
  .backup-config-modal {
    max-width: 95%;
    max-height: 95vh;
  }

  .config-header {
    padding: 16px 20px;

    h3 {
      font-size: 18px;
    }
  }

  .config-tabs {
    padding: 0 16px;

    .tab {
      padding: 10px 16px;
      font-size: 13px;
    }
  }

  .config-panel {
    padding: 16px;
  }

  .provider-header {
    flex-wrap: wrap;
  }

  .path-input {
    flex-direction: column;

    .btn-browse {
      width: 100%;
    }
  }

  .config-footer {
    flex-direction: column;
    gap: 10px;

    .btn-cancel,
    .btn-save {
      width: 100%;
      text-align: center;
    }
  }
}

@media (max-width: 480px) {
  .provider-header {
    .provider-icon {
      font-size: 20px;
    }

    .provider-name {
      font-size: 13px;
    }
  }

  .form-control {
    padding: 10px 14px;
    font-size: 13px;
  }

  .btn-test,
  .btn-browse {
    padding: 8px 12px;
    font-size: 12px;
  }
}

  `]
})
export class BackupConfigComponent implements OnInit {
  @Output() close = new EventEmitter<void>();
  @Output() save = new EventEmitter<BackupConfig>();  // ✅ CORREGIDO: añadir new
  @Input() proveedorSeleccionado: string = '';
  activeTab = 'cloud';
  testing = false;

  cloudProviders: CloudProvider[] = [
    { value: 'backblaze', label: 'Backblaze B2', icon: '☁️', enabled: false, apiKey: '', apiSecret: '', testResult: '', testSuccess: false },
    { value: 'mega', label: 'MEGA', icon: '🔒', enabled: false, apiKey: '', apiSecret: '', testResult: '', testSuccess: false },
    { value: 'onedrive', label: 'OneDrive', icon: '📁', enabled: false, apiKey: '', apiSecret: '', testResult: '', testSuccess: false },
    { value: 'dropbox', label: 'Dropbox', icon: '📦', enabled: false, apiKey: '', apiSecret: '', testResult: '', testSuccess: false }
  ];

  defaultCompressionLevel = 5;
  compressByDefault = true;
  defaultPath = 'storage/backups';

  constructor() {
    this.loadSavedConfig();
  }


   ngOnInit() {
    console.log('BackupConfigComponent ngOnInit, proveedorSeleccionado:', this.proveedorSeleccionado);
    if (this.proveedorSeleccionado) {
      this.activeTab = 'cloud';
      const provider = this.cloudProviders.find(p => p.value === this.proveedorSeleccionado);
      if (provider) {
        provider.enabled = true;
        setTimeout(() => {
          const cards = document.querySelectorAll('.provider-card');
          cards.forEach((card, index) => {
            if (index === this.cloudProviders.findIndex(p => p.value === this.proveedorSeleccionado)) {
              card.scrollIntoView({ behavior: 'smooth', block: 'center' });
              card.classList.add('highlight');
              setTimeout(() => card.classList.remove('highlight'), 2000);
            }
          });
        }, 100);
      }
    }
  }

  loadSavedConfig() {
    const saved = localStorage.getItem('backup_config');
    if (saved) {
      const config: BackupConfig = JSON.parse(saved);
      this.defaultCompressionLevel = config.compressionLevel || 5;
      this.compressByDefault = config.compressByDefault !== false;
      this.defaultPath = config.defaultPath || 'storage/backups';

      if (config.cloudProviders) {
        this.cloudProviders.forEach(provider => {
          const savedProvider = config.cloudProviders[provider.value];
          if (savedProvider) {
            provider.enabled = savedProvider.enabled;
            provider.apiKey = savedProvider.apiKey || '';
            provider.apiSecret = savedProvider.apiSecret || '';
          }
        });
      }
    }
  }

  onProviderToggle(provider: CloudProvider) {
    if (!provider.enabled) {
      provider.apiKey = '';
      provider.apiSecret = '';
      provider.testResult = '';
    }
  }

  testConnection(provider: CloudProvider) {
    this.testing = true;
    provider.testResult = 'Probando conexión...';

    // Simular prueba de conexión
    setTimeout(() => {
      this.testing = false;
      if (provider.apiKey && provider.apiKey.length > 10) {
        provider.testSuccess = true;
        provider.testResult = '✅ Conexión exitosa con ' + provider.label;
      } else {
        provider.testSuccess = false;
        provider.testResult = '❌ Error: API Key inválida o no configurada';
      }
    }, 1500);
  }

  selectDefaultPath() {
    // En una aplicación real, esto usaría un diálogo nativo
    const newPath = prompt('Ingrese la ruta para backups locales:', this.defaultPath);
    if (newPath && newPath.trim()) {
      this.defaultPath = newPath.trim();
    }
  }

  saveConfig() {
    // ✅ CORREGIDO: Definir el objeto con índice de tipo string
    const cloudProvidersConfig: { [key: string]: { enabled: boolean; apiKey: string; apiSecret: string } } = {};

    this.cloudProviders.forEach(provider => {
      cloudProvidersConfig[provider.value] = {
        enabled: provider.enabled,
        apiKey: provider.apiKey,
        apiSecret: provider.apiSecret
      };
    });

    const config: BackupConfig = {
      compressionLevel: this.defaultCompressionLevel,
      compressByDefault: this.compressByDefault,
      defaultPath: this.defaultPath,
      cloudProviders: cloudProvidersConfig
    };

    localStorage.setItem('backup_config', JSON.stringify(config));
    this.save.emit(config);
    this.onClose();
  }

  onClose() {
    this.close.emit();
  }

}

