// src/app/modules/backup-restore/presenters/backup-restore.presenter.ts
import { Injectable, OnDestroy } from '@angular/core';
import { BehaviorSubject, Observable, Subject } from 'rxjs';
import { takeUntil, map } from 'rxjs/operators';
import { BackupFacade } from '../facades/backup.facade';
import { BackupMonitorService } from '../../../services/backup-monitor.service';
import { RestoreMonitorService } from '../../../services/restore-monitor.service';
import { CloudSyncService } from '../../../services/cloud-sync.service';
import { ReportGeneratorService } from '../../../services/report-generator.service';
import { Backup, BackupRequest, RestoreRequest, BackupProgress } from '../models/backup.model';

export interface BackupRestoreViewModel {
  backups: Backup[];
  loading: boolean;
  pagination: any;
  showBackupModal: boolean;
  showRestoreModal: boolean;
  selectedBackupForRestore: Backup | null;
  backupEnProgreso: boolean;
  progresoBackup: BackupProgress | null;
  restauracionEnProgreso: boolean;
  progresoRestauracion: any;
  logsRestauracion: any[];
  showLogs: boolean;
  backupsCaducos: number;
  espacioLocalUsado: number;
  politicaRetencion: any;
  configuracionesNube: any[];
  proveedoresNubeActivos: string[];
  porcentajeExito: number;
  proximoBackupAuto: Date;
  isSidebarCollapsed: boolean;
  isDarkTheme: boolean;
}

const initialState: BackupRestoreViewModel = {
  backups: [],
  loading: false,
  pagination: null,
  showBackupModal: false,
  showRestoreModal: false,
  selectedBackupForRestore: null,
  backupEnProgreso: false,
  progresoBackup: null,
  restauracionEnProgreso: false,
  progresoRestauracion: {
    etapa_actual: '',
    detalle_etapa: '',
    porcentaje: 0,
    tiempo_estimado: '',
    tiempo_transcurrido: '00:00:00'
  },
  logsRestauracion: [],
  showLogs: false,
  backupsCaducos: 0,
  espacioLocalUsado: 0,
  politicaRetencion: { max_espacio_local: 10000 },
  configuracionesNube: [],
  proveedoresNubeActivos: [],
  porcentajeExito: 100,
  proximoBackupAuto: new Date(),
  isSidebarCollapsed: false,
  isDarkTheme: false
};

@Injectable()
export class BackupRestorePresenter implements OnDestroy {
  private viewModelSubject = new BehaviorSubject<BackupRestoreViewModel>(initialState);
  public viewModel$ = this.viewModelSubject.asObservable();

  private destroy$ = new Subject<void>();

  constructor(
    private backupFacade: BackupFacade,
    private backupMonitor: BackupMonitorService,
    private restoreMonitor: RestoreMonitorService,
    private cloudSync: CloudSyncService,
    private reportGenerator: ReportGeneratorService
  ) {
    this.initializeSubscriptions();
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  init(): void {
    this.loadBackups();
    this.loadCloudConfigurations();
    this.scheduleNextBackup();
  }

  destroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  private initializeSubscriptions(): void {
    // Suscripción a backups
    this.backupFacade.backups$
      .pipe(takeUntil(this.destroy$))
      .subscribe(backups => {
        this.updateState({ backups });
        this.calculateExpiredBackups(backups);
        this.calculateSuccessRate(backups);
        this.calculateUsedSpace(backups);
      });

    this.backupFacade.loading$
      .pipe(takeUntil(this.destroy$))
      .subscribe(loading => this.updateState({ loading }));

    this.backupFacade.pagination$
      .pipe(takeUntil(this.destroy$))
      .subscribe(pagination => this.updateState({ pagination }));

    // Suscripción al progreso de backup
    this.backupMonitor.backupProgress$
      .pipe(takeUntil(this.destroy$))
      .subscribe(progress => {
        this.updateState({
          backupEnProgreso: !!progress,
          progresoBackup: progress
        });
      });

    // Suscripción al progreso de restauración
    this.restoreMonitor.restoreProgress$
      .pipe(takeUntil(this.destroy$))
      .subscribe(progress => {
        this.updateState({
          restauracionEnProgreso: !!progress,
          progresoRestauracion: progress || initialState.progresoRestauracion
        });
      });

    this.restoreMonitor.restoreLogs$
      .pipe(takeUntil(this.destroy$))
      .subscribe(logs => this.updateState({ logsRestauracion: logs }));
  }

  // Acciones de UI
  loadBackups(page: number = 1): void {
    this.backupFacade.loadBackups(page);
  }

createBackup(request: BackupRequest): void {
  this.backupMonitor.startBackup(request);
  this.backupFacade.createBackup(request).subscribe(backup => {
    if (backup) {
      this.closeBackupModal();
      this.loadBackups();
    }
  });
}

createQuickBackup(request: BackupRequest): void {
  // CORREGIDO: NO asignar ninguna ruta aquí
  // Si no hay ruta, el backend usará la carpeta temporal
  if (!request.ruta_archivo_local || request.ruta_archivo_local.trim() === '') {
    // Eliminar la propiedad para que el backend use su ruta por defecto
    delete request.ruta_archivo_local;
  }
  this.createBackup(request);
}

  deleteBackup(id: number): void {
    this.backupFacade.deleteBackup(id).subscribe(success => {
      if (success) this.loadBackups();
    });
  }

  downloadBackup(id: number): void {
    const backup = this.getCurrentState().backups.find(b => b.backup_id === id);
    this.backupFacade.downloadBackup(id, `backup_${backup?.descripcion || id}_${Date.now()}.zip`);
  }
private loadCloudConfigurations(): void {
    this.cloudSync.getCloudConfigurations().subscribe(configs => {
        this.updateState({ configuracionesNube: configs });

        // Probar conexiones secuencialmente o en paralelo
        configs.forEach(config => {
            // Asegúrate de que 'testConnection' devuelva un observable que el facade maneje
            this.cloudSync.testConnection(config.proveedor).subscribe({
                next: (result) => {
                    if (result.success) {
                        const currentActivos = this.getCurrentState().proveedoresNubeActivos;
                        if (!currentActivos.includes(config.proveedor)) {
                            this.updateState({
                                proveedoresNubeActivos: [...currentActivos, config.proveedor]
                            });
                            // También actualiza el estado 'activo' en configuracionesNube
                            const updatedConfigs = this.getCurrentState().configuracionesNube.map(c =>
                                c.proveedor === config.proveedor ? { ...c, activo: true, connected: true } : c
                            );
                            this.updateState({ configuracionesNube: updatedConfigs });
                        }
                    } else {
                        // Actualizar a 'desconectado' si la prueba falla
                        const updatedConfigs = this.getCurrentState().configuracionesNube.map(c =>
                            c.proveedor === config.proveedor ? { ...c, activo: false, connected: false, error: result.message } : c
                        );
                        this.updateState({ configuracionesNube: updatedConfigs });
                    }
                },
                error: (error) => {
                    console.error(`Error probando conexión con ${config.proveedor}`, error);
                    const updatedConfigs = this.getCurrentState().configuracionesNube.map(c =>
                        c.proveedor === config.proveedor ? { ...c, activo: false, connected: false, error: 'Error de conexión' } : c
                    );
                    this.updateState({ configuracionesNube: updatedConfigs });
                }
            });
        });
    });
}
 restoreBackup(id: number): void {
  console.log('🔄 Presenter: Restaurando backup ID:', id);
  const backup = this.getCurrentState().backups.find(b => b.backup_id === id);
  if (backup) {
    this.updateState({
      showRestoreModal: true,
      selectedBackupForRestore: backup
    });
  } else {
    console.error('❌ Backup no encontrado para restaurar:', id);
  }
}

 confirmRestore(request: RestoreRequest): void {
  console.log('🔄 Iniciando restauración desde presenter:', request);
  this.closeRestoreModal();

  // CORREGIDO: Llamar al facade para restaurar
  this.backupFacade.restoreBackup(request).subscribe({
    next: (result) => {
      console.log('✅ Restauración exitosa:', result);
      this.backupFacade.showSuccess('Restauración completada', 'El sistema ha sido restaurado exitosamente');
    },
    error: (error) => {
      console.error('❌ Error en restauración:', error);
      this.backupFacade.showError('Error en restauración', error.message || 'Ocurrió un error');
    }
  });
}

  changePage(page: number): void {
    this.loadBackups(page);
  }

  openBackupModal(): void {
    this.updateState({ showBackupModal: true });
  }

  closeBackupModal(): void {
    this.updateState({ showBackupModal: false });
  }

  closeRestoreModal(): void {
    this.updateState({
      showRestoreModal: false,
      selectedBackupForRestore: null
    });
  }


  generateReports(): void {
    this.reportGenerator.generateFullReport();
  }

  openSettings(): void {
    this.backupFacade.showInfo('Configuración', 'Abriendo configuración de backups');
  }

  generateActivityReport(): void {
    this.reportGenerator.generateActivityReport();
  }

  viewFullActivity(): void {
    this.reportGenerator.generateHistoricalReport();
  }

  isProviderActive(provider: string): boolean {
    return this.getCurrentState().proveedoresNubeActivos.includes(provider);
  }

  hasUnvalidatedBackups(): boolean {
    return this.getCurrentState().backups.some(b => !b.integridad_verificada);
  }

  // Métodos privados
  private updateState(partial: Partial<BackupRestoreViewModel>): void {
    const current = this.getCurrentState();
    this.viewModelSubject.next({ ...current, ...partial });
  }

  private calculateExpiredBackups(backups: Backup[]): void {
    const fechaLimite = new Date();
    fechaLimite.setDate(fechaLimite.getDate() - 30);

    const backupsCaducos = backups.filter(backup =>
      new Date(backup.fecha) < fechaLimite
    ).length;

    this.updateState({ backupsCaducos });
  }

  private calculateSuccessRate(backups: Backup[]): void {
    const completed = backups.filter(b => b.estado === 'completado').length;
    const porcentajeExito = backups.length > 0 ? Math.round((completed / backups.length) * 100) : 100;
    this.updateState({ porcentajeExito });
  }

  private calculateUsedSpace(backups: Backup[]): void {
    const espacioLocalUsado = backups
      .filter(b => b.origen_nube === 'local')
      .reduce((total, b) => total + (b.tamanio_mb || 0), 0);

    this.updateState({ espacioLocalUsado });
  }


validateBackup(id: number): void {
    this.backupFacade.validateIntegrity(id).subscribe({
        next: (isValid) => {
            if (isValid) {
                // Actualizar el estado del backup en la lista local
                const currentState = this.getCurrentState();
                const updatedBackups = currentState.backups.map(b =>
                    b.backup_id === id ? { ...b, integridad_verificada: true } : b
                );
                this.updateState({ backups: updatedBackups });
                this.backupFacade.showSuccess('Validación exitosa', `El backup #${id} es válido.`);
            } else {
                this.backupFacade.showWarning('Validación fallida', `El backup #${id} no es válido o está corrupto.`);
            }
        },
        error: (err) => {
            this.backupFacade.showError('Error en validación', `No se pudo validar el backup #${id}.`);
            console.error(err);
        }
    });
}

// 2. Modifica el método 'validateAllBackups' para manejar múltiples validaciones
validateAllBackups(): void {
    const unvalidated = this.getCurrentState().backups.filter(b => !b.integridad_verificada);
    if (unvalidated.length === 0) {
        this.backupFacade.showInfo('Sin backups pendientes', 'Todos los backups ya están validados.');
        return;
    }

    this.backupFacade.showInfo('Validando', `Iniciando validación de ${unvalidated.length} backups...`);
    let completed = 0;
    let validCount = 0;

    unvalidated.forEach(backup => {
        this.backupFacade.validateIntegrity(backup.backup_id).subscribe({
            next: (isValid) => {
                completed++;
                if (isValid) validCount++;

                // Actualizar estado del backup individual
                const currentState = this.getCurrentState();
                const updatedBackups = currentState.backups.map(b =>
                    b.backup_id === backup.backup_id ? { ...b, integridad_verificada: isValid } : b
                );
                this.updateState({ backups: updatedBackups });

                // Mostrar progreso
                this.backupFacade.showInfo('Validando', `Progreso: ${completed}/${unvalidated.length}`);

                if (completed === unvalidated.length) {
                    this.backupFacade.showSuccess('Validación completa', `${validCount} de ${unvalidated.length} backups son válidos.`);
                }
            },
            error: () => {
                completed++;
                if (completed === unvalidated.length) {
                    this.backupFacade.showWarning('Validación completa', `${validCount} de ${unvalidated.length} backups son válidos.`);
                }
            }
        });
    });
}

updateProveedoresActivos(activos: string[]): void {
  this.updateState({ proveedoresNubeActivos: activos });
}

public getCurrentState(): BackupRestoreViewModel {
  return this.viewModelSubject.getValue();
}
// configureProvider - CORREGIDO
configureProvider(proveedor: string): void {
    this.backupFacade.showInfo('Configuración', `Configurando proveedor ${proveedor}`);
    this.openSettings(); // Abre el modal de configuración
}

syncWithCloud(): void {
    this.backupFacade.showInfo('Sincronización', 'Verificando conexión con servicios cloud...');

    // Probar conexión con cada proveedor configurado
    const providers = ['local', 'backblaze', 'onedrive', 'dropbox', 'mega'];
    let activeCount = 0;

    providers.forEach(provider => {
        this.backupFacade.testConnection(provider).subscribe({
            next: (result) => {
                if (result.success) {
                    activeCount++;
                    const currentActivos = this.getCurrentState().proveedoresNubeActivos;
                    if (!currentActivos.includes(provider)) {
                        this.updateState({
                            proveedoresNubeActivos: [...currentActivos, provider]
                        });
                    }
                    this.backupFacade.showSuccess(
                        `${this.backupFacade.getProviderLabel(provider)}`,
                        '✅ Conexión establecida'
                    );
                } else {
                    this.backupFacade.showWarning(
                        `${this.backupFacade.getProviderLabel(provider)}`,
                        result.message || '❌ Error de conexión'
                    );
                }
            },
            error: (error) => {
                this.backupFacade.showError(
                    `${this.backupFacade.getProviderLabel(provider)}`,
                    'No se pudo conectar'
                );
            }
        });
    });

    setTimeout(() => {
        this.backupFacade.showSuccess(
            'Sincronización completada',
            `${activeCount} servicios cloud disponibles`
        );
    }, 2000);
}
applyRetentionPolicy(): void {
    const expiredCount = this.getCurrentState().backupsCaducos;
    if (expiredCount === 0) {
        this.backupFacade.showInfo('Sin backups caducos', 'No hay backups que requieran limpieza');
        return;
    }

    this.backupFacade.showConfirm(
        'Aplicar Política de Retención',
        `¿Eliminar ${expiredCount} backups caducos?`,
        () => {
            const thirtyDaysAgo = new Date();
            thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);

            const toDelete = this.getCurrentState().backups.filter(b =>
                new Date(b.fecha) < thirtyDaysAgo
            );

            toDelete.forEach(backup => this.deleteBackup(backup.backup_id));
            this.backupFacade.showSuccess('Política aplicada', `${toDelete.length} backups eliminados`);
        }
    );
}


  private scheduleNextBackup(): void {
    const proximoBackupAuto = new Date();
    proximoBackupAuto.setHours(2, 0, 0, 0);
    if (new Date() > proximoBackupAuto) {
      proximoBackupAuto.setDate(proximoBackupAuto.getDate() + 1);
    }
    this.updateState({ proximoBackupAuto });
  }
  toggleLogs(): void {
  this.updateState({ showLogs: !this.getCurrentState().showLogs });
}
}
