import { Component, Input, Output, EventEmitter } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Backup } from '../../models/backup.model';
import { BackupFacade } from '../../facades/backup.facade';
import { NotificationService } from '../../../../core/services/notification/notification.service';


@Component({
  selector: 'app-backup-list',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './backup-list.component.html',
  styleUrls: ['./../../backup-restore.component.less']
})
export class BackupListComponent {
  @Input() backups: Backup[] = [];
  @Input() loading = false;
  @Input() pagination: any;

  @Output() pageChange = new EventEmitter<number>();
  @Output() backupDeleted = new EventEmitter<number>();
  @Output() backupDownloaded = new EventEmitter<number>();
  @Output() backupValidated = new EventEmitter<number>();
  @Output() backupRestored = new EventEmitter<number>();

  validating = false;
  validationResult: { valid: boolean; message: string } | null = null;
  restoreData = {
    modo_prueba: false,
    modo: 'completa' as 'completa' | 'parcial',
    observaciones: '',
    componentes: {
      base_datos: true,
      usuarios: true,
      configuracion: true,
      archivos: true,
      datos: true
    }
  };

  constructor(private backupFacade: BackupFacade, private notificationService: NotificationService ) {}

  onPageChange(page: number): void {
    this.pageChange.emit(page);
  }

  onRestore(backup: any, event: Event): void {
  event.stopPropagation();

  // CORREGIDO: Mostrar confirmación y emitir evento
  this.notificationService.showConfirm(
    'Restaurar Backup',
    `¿Está seguro que desea restaurar el backup "${backup.descripcion}"? Esta acción sobrescribirá datos actuales.`,
    () => {
      console.log('🔄 Confirmada restauración para backup ID:', backup.backup_id);
      this.backupRestored.emit(backup.backup_id);
    }
  );
}

  onCancel(): void {
    this.restoreData = {
      modo_prueba: false,
      modo: 'completa',
      observaciones: '',
      componentes: {
        base_datos: true,
        usuarios: true,
        configuracion: true,
        archivos: true,
        datos: true
      }
    };
  }

  onSubmit(): void {
    // Emitir evento de restauración
    this.backupRestored.emit(this.getCurrentBackup()?.backup_id);
  }

  getCurrentBackup(): Backup | null {
    return this.backups[0] || null;
  }

  getProviderIcon(origen?: string): string {
    if (!origen && this.getCurrentBackup()) {
      origen = this.getCurrentBackup()?.origen_nube;
    }
    return this.backupFacade.getProviderIcon(origen || 'local');
  }

  getProviderLabel(origen?: string): string {
    if (!origen && this.getCurrentBackup()) {
      origen = this.getCurrentBackup()?.origen_nube;
    }
    return this.backupFacade.getProviderLabel(origen || 'local');
  }

 getEstadoClass(backup: Backup): string {
  if (backup.estado === 'COMPLETADO') {
    if (!backup.integridad_verificada) return 'estado-error';
    const fechaBackup = new Date(backup.fecha);
    const ahora = new Date();
    const diferenciaDias = (ahora.getTime() - fechaBackup.getTime()) / (1000 * 60 * 60 * 24);
    if (diferenciaDias < 1) return 'estado-activo';
    if (diferenciaDias < 7) return 'estado-reciente';
    if (diferenciaDias < 30) return 'estado-normal';
    return 'estado-antiguo';
  }
  return 'estado-error';
}

  getEstadoTexto(backup: Backup): string {
    if (!backup.integridad_verificada) return 'Integridad fallida';

    const fechaBackup = new Date(backup.fecha);
    const ahora = new Date();
    const diferenciaDias = Math.floor((ahora.getTime() - fechaBackup.getTime()) / (1000 * 60 * 60 * 24));

    if (diferenciaDias < 1) return 'Hoy';
    if (diferenciaDias === 1) return 'Ayer';
    if (diferenciaDias < 7) return 'Esta semana';
    if (diferenciaDias < 30) return 'Este mes';
    return `${diferenciaDias} días`;
  }

  formatFileSize(sizeMB: number): string {
    if (sizeMB < 1) return `${(sizeMB * 1024).toFixed(2)} KB`;
    if (sizeMB < 1024) return `${sizeMB.toFixed(2)} MB`;
    return `${(sizeMB / 1024).toFixed(2)} GB`;
  }

  formatDate(date: Date): string {
    return new Date(date).toLocaleString('es-ES', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  }

  getPaginationArray(): (number | string)[] {
    const total = this.pagination?.last_page || 1;
    const current = this.pagination?.current_page || 1;
    return this.generatePaginationArray(total, current);
  }

  private generatePaginationArray(total: number, current: number): (number | string)[] {
    const delta = 2;
    const range: number[] = [];
    const rangeWithDots: (number | string)[] = [];

    for (let i = 1; i <= total; i++) {
      if (i === 1 || i === total || (i >= current - delta && i <= current + delta)) {
        range.push(i);
      }
    }

    let prev = 0;
    for (const i of range) {
      if (prev !== 0) {
        if (i - prev === 2) {
          rangeWithDots.push(prev + 1);
        } else if (i - prev !== 1) {
          rangeWithDots.push('...');
        }
      }
      rangeWithDots.push(i);
      prev = i;
    }

    return rangeWithDots;
  }
   onPageChangeNumero(pagina: number | string): void {
    if (typeof pagina === 'number') {
      this.onPageChange(pagina);
    }
  }
onValidate(backup: any): void {
  this.notificationService.showConfirm(
    'Validar Backup',
    `¿Desea validar la integridad del backup "${backup.descripcion}"?`,
    () => {
      if (backup && backup.backup_id) {
        this.backupValidated.emit(backup.backup_id);
      }
    }
  );
}

onDelete(backup: any): void {
  this.notificationService.showConfirm(
    'Eliminar Backup',
    `¿Está seguro que desea eliminar el backup "${backup.descripcion}"? Esta acción no se puede deshacer.`,
    () => {
      if (backup && backup.backup_id) {
        this.backupDeleted.emit(backup.backup_id);
      }
    }
  );
}

onDownload(backup: any): void {
  this.notificationService.showConfirm(
    'Descargar Backup',
    `¿Desea descargar el backup "${backup.descripcion}"?`,
    () => {
      if (backup && backup.backup_id) {
        this.backupDownloaded.emit(backup.backup_id);
      }
    }
  );
}
}
