import { Component, OnInit, OnDestroy, HostListener, ViewEncapsulation, AfterViewChecked} from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router, RouterModule } from '@angular/router';
import { trigger, transition, style, animate } from '@angular/animations';
import { Subject, Observable } from 'rxjs';
import { takeUntil } from 'rxjs/operators';
import { ChangeDetectorRef } from '@angular/core';

import { MenuComponent } from '../../layouts/menu/menu.component';
import { FooterComponent } from '../../layouts/footer/footer.component';
import { HeaderComponent } from '../../layouts/header/header.component';
import { HelpSupportComponent } from '../dashboard/components/help-support/help-support.component';
import { NotificationService } from './../../core/services/notification/notification.service';
import { AuthService } from '../../core/services/auth.service';
import { BackupConfigComponent } from './components/backup-config/backup-config.component';
import { ThemeService, ThemeType } from '../../shared/features/home/services/theme.service';

import { BackupListComponent } from './components/backup-list/backup-list.component';
import { BackupFormComponent } from './components/backup-form/backup-form.component';
import { RestoreModalComponent } from './components/restore-modal/restore-modal.component';
import { BackupFacade } from './facades/backup.facade';
import { BackupRestorePresenter, BackupRestoreViewModel } from './presenters/backup-restore.presenter';
import { Backup, BackupRequest, RestoreRequest } from './models/backup.model';
import { LoadingService } from '../../core/services/loading.service';
import { ModuleLoaderService } from '../../core/services/module-loader.service';

@Component({
  selector: 'app-backup-restore',
  standalone: true,
  encapsulation: ViewEncapsulation.None,
  imports: [
    CommonModule,
    FormsModule,
    RouterModule,
    MenuComponent,
    HeaderComponent,
    FooterComponent,
    BackupConfigComponent,
    HelpSupportComponent,
    BackupListComponent,
    BackupFormComponent,
    RestoreModalComponent
  ],
  templateUrl: './backup-restore.component.html',
  styleUrls: ['./backup-restore.component.less'],
  providers: [BackupRestorePresenter],
  animations: [
    trigger('slideDown', [
      transition(':enter', [
        style({ opacity: 0, transform: 'translateY(-20px)' }),
        animate('300ms cubic-bezier(0.4, 0, 0.2, 1)',
          style({ opacity: 1, transform: 'translateY(0)' }))
      ]),
      transition(':leave', [
        animate('200ms cubic-bezier(0.4, 0, 0.2, 1)',
          style({ opacity: 0, transform: 'translateY(-20px)' }))
      ])
    ]),
    trigger('fadeIn', [
      transition(':enter', [
        style({ opacity: 0, transform: 'translateY(-10px)' }),
        animate('200ms ease-out', style({ opacity: 1, transform: 'translateY(0)' }))
      ]),
      transition(':leave', [
        animate('150ms ease-in', style({ opacity: 0, transform: 'translateY(-10px)' }))
      ])
    ])
  ]
})
export class BackupRestoreComponent implements OnInit, OnDestroy, AfterViewChecked {
     private moduleName = 'Gestión de Respaldo y Restauración';
  private dataLoaded = false;
  private isMarkedReady = false;
  private viewCheckedCount = 0;
  private destroy$ = new Subject<void>();

  viewModel$!: Observable<BackupRestoreViewModel>;

  // Variables para el layout
  isSidebarCollapsed = false;
  currentTheme: ThemeType = 'light';
  showHelpSupport = false;
  isMinimized = false;
  showMinimizeNotification = false;
  minimizing = false;

  // Variables para modales
  isSearchOpen = false;
  isNotificationsOpen = false;
  isUserMenuOpen = false;
  searchQuery = '';
  searchResults: any[] = [];
  showConfigModal = false;
  proveedorSeleccionado: string = '';
  showSyncIndividualModal = false;
proveedoresDisponibles: { value: string; label: string; icon: string; seleccionado: boolean }[] = [];
  showSyncModal = false;
sincronizando = false;
proveedoresSincronizacion: { nombre: string; estado: 'pendiente' | 'conectando' | 'conectado' | 'error'; mensaje?: string }[] = [];
proveedoresConectados: string[] = [];

  // Variables del viewModel
  showBackupModal = false;
  showRestoreModal = false;

  // Configuración de usuario
  user = {
    name: 'Admin SIGPAZ',
    email: 'admin@sigpaz.com',
    avatar: 'A'
  };

  constructor(
    private router: Router,
    private notificationService: NotificationService,
    private authService: AuthService,
    private cdr: ChangeDetectorRef,
    private backupFacade: BackupFacade,
     private moduleLoader: ModuleLoaderService,
        private loadingService: LoadingService,
    private presenter: BackupRestorePresenter,
    private themeService: ThemeService
  ) {
    this.viewModel$ = this.presenter.viewModel$;
  }

  ngOnInit(): void {
    this.setupThemeSubscription();
    this.setupKeyboardShortcuts();
    this.moduleLoader.registerComponentInstance(this.moduleName, this);
    this.loadModuleData();
    // Inicializar el presenter
    this.presenter.init();

    // Suscribirse a cambios del viewModel
    this.viewModel$.pipe(takeUntil(this.destroy$)).subscribe(vm => {
      this.showBackupModal = vm.showBackupModal;
      this.showRestoreModal = vm.showRestoreModal;
       this.cdr.detectChanges();
    });

    // Cargar usuario actual
    const user = this.authService.getCurrentUser();
    if (user) {
      this.user.name = user.nombre_usuario || 'Usuario';
      this.user.email = user.email || '';
    }

  }


  ngAfterViewChecked() {
    // Después de cada verificación de vista, si ya está marcado, no hacer nada
    if (this.isMarkedReady) return;

    this.viewCheckedCount++;

    // Esperar a que Angular termine de renderizar completamente
    if (this.dataLoaded && this.viewCheckedCount >= 2) {
      console.log(`✅ Vista completamente estable (afterViewChecked x${this.viewCheckedCount})`);
      this.checkAndMarkReady();
    }
  }

  private async loadModuleData(): Promise<void> {
    try {
      console.log(`📡 Cargando datos para: ${this.moduleName}`);

        await Promise.all([
      this.sincronizarProveedorSeleccionado(),            // Cargar proveedores
      this.sincronizarConNube()      // Sincronizar con la nube
    ]);

      this.dataLoaded = true;
      console.log(`✅ Datos cargados para: ${this.moduleName}`);

      // Forzar detección de cambios
      setTimeout(() => {
        this.checkAndMarkReady();
      }, 100);

    } catch (error) {
      console.error(`❌ Error cargando datos:`, error);
      this.markModuleAsReady(); // Ocultar loading aunque haya error
    }
  }

 private checkAndMarkReady(): void {
  if (this.isMarkedReady) return;

  const hasContent = document.querySelector('.backup-container, .main-content, app-backup-restore');
  const hasData = document.querySelector('.backup-container, .monitoring-panel, .quick-status, .alerts-list');

  console.log(`🔍 [Backup] Verificando contenido: hasContent=${!!hasContent}, hasData=${!!hasData}`);

  if (this.dataLoaded && hasContent && hasData) {
    this.markModuleAsReady();
  } else if (this.dataLoaded) {
    setTimeout(() => this.checkAndMarkReady(), 200);
  }
}

  private markModuleAsReady(): void {
    if (this.isMarkedReady) return;
    this.isMarkedReady = true;
    console.log(`🏁 Marcando módulo como listo: ${this.moduleName}`);
    this.moduleLoader.markModuleRendered(this.moduleName);
  }

  private fetchData(url: string): Promise<any> {
    return new Promise(resolve => setTimeout(resolve, 500));
  }

    private setupThemeSubscription(): void {
        this.themeService.theme$
          .pipe(takeUntil(this.destroy$))
          .subscribe(theme => {
            this.currentTheme = theme;
          });
      }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
    this.presenter.destroy();
     this.moduleLoader.markModuleRendered(this.moduleName);
  }

  configurarProveedorIndividual(proveedor: string): void {
  console.log('Configurando proveedor:', proveedor);
  // Abrir modal de configuración con el proveedor seleccionado
  this.proveedorSeleccionado = proveedor;
  this.showConfigModal = true;
}

  // ========== MÉTODOS DEL LAYOUT ==========
  onToggleSidebar(): void {
    this.isSidebarCollapsed = !this.isSidebarCollapsed;
  }

  onToggleHelpSupport(): void {
    this.showHelpSupport = !this.showHelpSupport;
    if (!this.showHelpSupport) {
      document.body.classList.remove('minimized-mode');
    }
  }



  onToggleNotifications(): void {
    this.isNotificationsOpen = !this.isNotificationsOpen;
    if (this.isNotificationsOpen) this.isUserMenuOpen = false;
  }

  onToggleUserMenu(): void {
    this.isUserMenuOpen = !this.isUserMenuOpen;
    if (this.isUserMenuOpen) this.isNotificationsOpen = false;
  }

  onMarkAllAsRead(): void {
    this.notificationService.showInfo('Todas las notificaciones marcadas como leídas');
  }

  onOpenSearchModal(): void {
    this.isSearchOpen = true;
    this.isNotificationsOpen = false;
    this.isUserMenuOpen = false;
  }

  closeSearchModal(): void {
    this.isSearchOpen = false;
    this.searchQuery = '';
    this.searchResults = [];
  }

  performSearch(): void {
    if (this.searchQuery.trim()) {
      this.closeSearchModal();
    }
  }

  clearSearch(): void {
    this.searchQuery = '';
    this.searchResults = [];
  }

  // ========== MÉTODOS DEL MODAL DE AYUDA ==========
  minimizeToBubble(): void {
    this.isMinimized = true;
    document.body.classList.add('minimized-mode');
    setTimeout(() => {
      this.minimizing = false;
      this.showMinimizeNotification = true;
      setTimeout(() => this.showMinimizeNotification = false, 3000);
    }, 300);
  }

  restoreFromBubble(): void {
    this.isMinimized = false;
    document.body.classList.remove('minimized-mode');
  }

  closeBubble(event: MouseEvent): void {
    event.stopPropagation();
    this.showHelpSupport = false;
    this.isMinimized = false;
  }

  handleOverlayClick(event: MouseEvent): void {
    if ((event.target as HTMLElement).classList.contains('modal-overlay-sigpaz')) {
      if (this.showHelpSupport && !this.isMinimized) {
        this.minimizeToBubble();
      }
    }
  }


  // ========== MÉTODOS PRIVADOS ==========

  private setupKeyboardShortcuts(): void {
    document.addEventListener('keydown', (event) => {
      if ((event.ctrlKey || event.metaKey) && event.key === 'k') {
        event.preventDefault();
        this.onOpenSearchModal();
      }

      if (event.key === 'Escape') {
        if (this.isSearchOpen) this.closeSearchModal();
        if (this.isNotificationsOpen) this.isNotificationsOpen = false;
        if (this.isUserMenuOpen) this.isUserMenuOpen = false;
        if (this.showBackupModal) this.closeBackupModal();
        if (this.showRestoreModal) this.closeRestoreModal();
      }
    });
  }

  @HostListener('document:click', ['$event'])
  onClickOutside(event: MouseEvent): void {
    const target = event.target as HTMLElement;

    if (!target.closest('.notification-wrapper') && !target.closest('.notifications-dropdown')) {
      this.isNotificationsOpen = false;
    }

    if (!target.closest('.user-menu-wrapper') && !target.closest('.user-dropdown')) {
      this.isUserMenuOpen = false;
    }

    if (!target.closest('.search-modal-content') &&
        !target.closest('.search-button') &&
        !target.closest('.sidebar-search')) {
      this.isSearchOpen = false;
    }
  }

  // ========== MÉTODOS DE BACKUP ==========
  onCreateBackup(request: BackupRequest): void {
    this.presenter.createBackup(request);
  }

  onDeleteBackup(id: number): void {
    this.presenter.deleteBackup(id);
  }

  onDownloadBackup(id: number): void {
    this.presenter.downloadBackup(id);
  }

  onValidateBackup(id: number): void {
    this.presenter.validateBackup(id);
  }

  onRestoreBackup(id: number): void {
    this.presenter.restoreBackup(id);
  }

  onConfirmRestore(request: RestoreRequest): void {
  console.log('✅ Confirmando restauración:', request);
  this.presenter.confirmRestore(request);
}

  onPageChange(page: number): void {
    this.presenter.changePage(page);
  }

  crearBackupManual(): void {
    this.presenter.openBackupModal();
  }

  aplicarPoliticaRetencion(): void {
    this.presenter.applyRetentionPolicy();
  }

  validarIntegridadBackups(): void {
    this.presenter.validateAllBackups();
  }

  generarReportesCompletos(): void {
    this.presenter.generateReports();
  }

  generarReporteActividad(): void {
    this.presenter.generateActivityReport();
  }

  verActividadCompleta(): void {
    this.presenter.viewFullActivity();
  }

  proveedorActivo(proveedor: string): boolean {
    // El backup local SIEMPRE está activo
    if (proveedor === 'local') return true;
    return this.presenter.isProviderActive(proveedor);
  }

  tieneBackupsSinValidar(): boolean {
    return this.presenter.hasUnvalidatedBackups();
  }

  closeBackupModal(): void {
    this.presenter.closeBackupModal();
  }

  closeRestoreModal(): void {
    this.presenter.closeRestoreModal();
  }

  toggleLogs(): void {
    this.presenter.toggleLogs();
  }

  get unreadNotificationsCount(): number {
    return 0;
  }

  onBackupValidated(backupId: number): void {
  console.log('Backup a validar ID:', backupId);
  this.presenter.validateBackup(backupId);
}

onBackupDeleted(backupId: number): void {
  console.log('Backup a eliminar ID:', backupId);
  this.presenter.deleteBackup(backupId);
}

onBackupDownloaded(backupId: number): void {
  console.log('Backup a descargar ID:', backupId);
  this.presenter.downloadBackup(backupId);
}
// backup-restore.component.ts

crearBackupRapido(): void {
  // Mostrar confirmación antes de crear backup rápido
  this.notificationService.showConfirm(
    'Backup Rápido',
    '¿Desea crear un backup rápido en la ubicación por defecto?',
    () => {
      // Crear backup con configuración por defecto
      const quickBackupRequest: BackupRequest = {
        descripcion: 'Backup rápido automático - ' + new Date().toLocaleString(),
        origen_nube: 'local',
        tipo: 'completo',
        ruta_archivo_local: '',  // Vacío para que use la ruta por defecto
        api_referencia: '',
        encriptar: false,
        comprimir: true,
        nivel_compresion: 5,
        password_encriptacion: '',
      };

      this.presenter.createQuickBackup(quickBackupRequest);
    }
  );
}


// Asegurar que el método esté correctamente definido
abrirConfiguracionBackup(): void {
  console.log('Abriendo configuración de backup');
  this.showConfigModal = true;
}

closeConfigModal(): void {
  this.showConfigModal = false;
}

saveConfig(config: any): void {
  console.log('Guardando configuración:', config);
  this.showConfigModal = false;
  this.notificationService.showSuccess('Configuración de backup guardada correctamente');

  // Actualizar configuración en el servicio
  localStorage.setItem('backup_config', JSON.stringify(config));
}

sincronizarConNube(): void {
  // Inicializar lista de proveedores (solo cloud, no local)
  const proveedoresCloud = ['backblaze', 'onedrive', 'dropbox', 'mega'];

  this.proveedoresSincronizacion = proveedoresCloud.map(p => ({
    nombre: this.getProviderLabel(p),
    estado: 'pendiente'
  }));

  this.showSyncModal = true;
  this.sincronizando = true;
  this.proveedoresConectados = [];

  this.sincronizarProveedorSecuencial(0);
}

private getProviderLabel(provider: string): string {
  const labels: {[key: string]: string} = {
    'backblaze': 'Backblaze B2',
    'onedrive': 'OneDrive',
    'dropbox': 'Dropbox',
    'mega': 'MEGA',
    'local': 'Almacenamiento Local'
  };
  return labels[provider] || provider;
}

private sincronizarProveedorSecuencial(index: number): void {
  if (index >= this.proveedoresSincronizacion.length) {
    // Finalizar sincronización
    this.sincronizando = false;
    setTimeout(() => {
      const mensaje = this.proveedoresConectados.length > 0
        ? `${this.proveedoresConectados.length} servicios cloud conectados`
        : 'No se pudo conectar ningún servicio cloud';
      this.notificationService.showSuccess('Sincronización completada');
      setTimeout(() => {
        this.showSyncModal = false;
      }, 2000);
    }, 1000);
    return;
  }

  const proveedor = this.proveedoresSincronizacion[index];
  const providerValue = this.getProviderValue(proveedor.nombre);

  // Actualizar estado a conectando
  proveedor.estado = 'conectando';

  this.backupFacade.testConnection(providerValue).subscribe({
    next: (result) => {
      if (result.success) {
        proveedor.estado = 'conectado';
        proveedor.mensaje = '✅ Conectado';
        this.proveedoresConectados.push(providerValue);

        // Actualizar proveedores activos en el estado
        const currentActivos = this.presenter.getCurrentState().proveedoresNubeActivos;
        if (!currentActivos.includes(providerValue)) {
          this.presenter.updateProveedoresActivos([...currentActivos, providerValue]);
        }
      } else {
        proveedor.estado = 'error';
        proveedor.mensaje = result.message || '❌ Error de conexión';
      }

      // Continuar con el siguiente después de 500ms
      setTimeout(() => {
        this.sincronizarProveedorSecuencial(index + 1);
      }, 500);
    },
    error: () => {
      proveedor.estado = 'error';
      proveedor.mensaje = '❌ No se pudo conectar';

      setTimeout(() => {
        this.sincronizarProveedorSecuencial(index + 1);
      }, 500);
    }
  });
}

private getProviderValue(label: string): string {
  const values: {[key: string]: string} = {
    'Backblaze B2': 'backblaze',
    'OneDrive': 'onedrive',
    'Dropbox': 'dropbox',
    'MEGA': 'mega'
  };
  return values[label] || label.toLowerCase();
}

cerrarSyncModal(): void {
  if (!this.sincronizando) {
    this.showSyncModal = false;
  }
}
sincronizarIndividual(): void {
  // Cargar proveedores disponibles (solo cloud)
  this.proveedoresDisponibles = [
    { value: 'backblaze', label: 'Backblaze B2', icon: '☁️', seleccionado: false },
    { value: 'onedrive', label: 'OneDrive', icon: '📁', seleccionado: false },
    { value: 'dropbox', label: 'Dropbox', icon: '📦', seleccionado: false },
    { value: 'mega', label: 'MEGA', icon: '🔒', seleccionado: false }
  ];

  this.showSyncIndividualModal = true;
}

sincronizarProveedorSeleccionado(): void {
  const seleccionados = this.proveedoresDisponibles.filter(p => p.seleccionado);

  if (seleccionados.length === 0) {
    this.notificationService.showWarning('Seleccione al menos un proveedor');
    return;
  }

  this.showSyncIndividualModal = false;
  this.sincronizando = true;

  // Sincronizar proveedores seleccionados
  let completados = 0;

  seleccionados.forEach(proveedor => {
    this.backupFacade.testConnection(proveedor.value).subscribe({
      next: (result) => {
        completados++;
        if (result.success) {
          this.notificationService.showSuccess(proveedor.label);
          // Actualizar estado
          const currentActivos = this.presenter.getCurrentState().proveedoresNubeActivos;
          if (!currentActivos.includes(proveedor.value)) {
            this.presenter.updateProveedoresActivos([...currentActivos, proveedor.value]);
          }
        } else {
          this.notificationService.showError(proveedor.label,);
        }

        if (completados === seleccionados.length) {
          this.sincronizando = false;
          this.notificationService.showSuccess(`${completados} servicios verificados`);
        }
      },
      error: () => {
        completados++;
        this.notificationService.showError(proveedor.label,);

        if (completados === seleccionados.length) {
          this.sincronizando = false;
        }
      }
    });
  });
}

cerrarSyncIndividualModal(): void {
  this.showSyncIndividualModal = false;
}

configurarProveedor(proveedor: string): void {
  console.log('Configurando proveedor individual desde alerta:', proveedor);
  // Abrir modal de configuración con el proveedor seleccionado
  this.proveedorSeleccionado = proveedor;
  this.showConfigModal = true;
}
}
